-- The official PSSR checklist for pipelines and related facilities (208 items: «فرم کامل چک لیست های PSSR برای خطوط لوله
-- و تاسیسات وابسته»): every item has its row number, area (اداری / محوطه / تأسیسات), group, priority A/B/C and the system
-- kinds it applies to. Answers keep the form's three columns: بلی = ok, خیر = fail, بدون کاربرد = na.
-- Priority A items must be «بلی» or «بدون کاربرد» before RFSU (mandatory); a «خیر» opens a punch of the item's priority.
-- The system carries the form's header (startup type, PSSR team leader, review date) and its six-statement summary.
alter table pssr_template_items add column if not exists area text not null default '', add column if not exists priority text not null default 'B',
  add column if not exists ref_no int, add column if not exists kinds text[], add column if not exists source text not null default '';
alter table pssr_checks add column if not exists area text not null default '', add column if not exists priority text not null default '', add column if not exists ref_no int;
alter table pssr_punches add column if not exists check_id uuid references pssr_checks (id) on delete set null;
alter table pssr_systems add column if not exists startup_type text not null default '', add column if not exists team_lead text not null default '',
  add column if not exists review_date date, add column if not exists summary jsonb not null default '{}'::jsonb;
create index if not exists pssr_punches_check on pssr_punches (check_id);

do $$ begin
  if not exists (select 1 from pssr_template_items where source = 'PSSR-PL-208') then
    -- the earlier sample template stays for the systems already built from it, but is no longer offered to new systems
    update pssr_template_items set is_active = false where source = '';
    insert into pssr_template_items (seq, ref_no, area, category, priority, title, kinds, kind, mandatory, source, is_active)
    select v.n, v.n, v.area, v.cat, v.p, v.t, v.k, case when array_length(v.k, 1) = 1 then v.k[1] else 'all' end, v.p = 'A', 'PSSR-PL-208', true
    from (values
  (1, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه های Plot Plan خط فوق و کلیه انشعابات و هات تپ به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (2, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه های ایزومتریک کلیه انشعابات و هات تپ به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (3, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه هایRoute & Profile خط فوق و کلیه انشعابات و هات تپ به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
