  (5, 'بخش اداری', 'نقشه‌ها', 'A', 'آیا ازبیلت(As Built) خط همراه با موقعیت ایستگاه حفاظت کاتدی، بستر و نقشه های مربوطه موجود می باشد ؟', array['all']::text[]),
  (6, 'بخش اداری', 'نقشه‌ها', 'A', 'آیا نقشه های Plot Plan و ایزومتریک ایستگاه های ارسال و دریافت توپک (L/R) خط فوق به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (7, 'بخش اداری', 'نقشه‌ها', 'A', 'آیا نقشه های Plot Plan و ایزومتریک ایستگاه یا ایستگاه های شیر بین راهی(V.S) خط فوق به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (8, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه های پلان ایستگاه های سیستم حفاظت کاتدی و بستر آندی، جانمایی مارکرها و باند باکس ها صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (9, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه های پلان و 200/1 تقاطع ها خط فوق به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (10, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا ازبیلت یا کروکی سیستم الکتریکال شبکه انتقال و توزیع برق خط فوق برای روشنایی ایستگاه ها و ایستگاه CPS به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (11, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا نقشه های سیویل (ایستگاه ها و ابنیه های فنی) خط فوق به صورت نرم افزاری و هارد کپی تهیه و ارایه گردیده است؟', array['all']::text[]),
  (12, 'بخش اداری', 'نقشه‌ها', 'B', 'آیا مشخصات فنی تهیه نقشه های ازبیلت(As Built) که توسط مجری طرح تحویل داده می شود، قابلیت پیادهسازی در نرمافزار و سیستم GIS را دارد؟', array['all']::text[]),
