  (14, 'بخش اداری', 'طراحی مهندسی', 'B', 'آیا مدارک طراحی و محاسبات مربوط به Anchor Force، Anchor Flange و Anchor Block استفاده شده در خط به صورت نرم افزاری و هارد کپی ارایه شده است؟', array['all']::text[]),
  (15, 'بخش اداری', 'طراحی مهندسی', 'B', 'آیا مدارک طراحی و ازبیلت و محاسبات سیستم حفاظت کاتدیک خط به صورت نرم افزاری و هارد کپی ارایه شده است؟', array['all']::text[]),
